/* Tide wiki front-end. Data comes from data.js (generated by tools/extract.py). */
(function () {
  "use strict";

  var T = window.TIDE;
  var X = T.extras;
  var PER_PAGE = 24;

  /* ------------------------------------------------------------ lookups */

  var icons = {}, names = {};
  function register(id, icon, name) {
    if (id) { if (icon) icons[id] = icon; if (name) names[id] = name; }
  }
  T.items.forEach(function (i) { register(i.id, i.icon, i.name); });
  T.fish.forEach(function (f) {
    register(f.id, f.icon, f.name);
    register(f.bucket, T.items.filter(function (i) { return i.id === f.bucket; })[0] ?
      (T.items.filter(function (i) { return i.id === f.bucket; })[0].icon) : null, null);
  });
  T.blocks.forEach(function (b) { register(b.id, b.icon, b.name); });
  T.baits.forEach(function (b) { register(b.item, b.icon, b.name); });
  T.lines.forEach(function (l) { register(l.item, l.icon, l.name); });
  T.vanillaFish.forEach(function (f) { register(f.id, null, f.name); });
  T.advancements.forEach(function (a) { register(a.id, a.icon, a.title); });
  /* lines and baits are generated with "item" instead of "id"; normalise so gear cards can use part.id */
  [T.lines, T.baits].forEach(function (list) {
    list.forEach(function (entry) { if (!entry.id) entry.id = entry.item; });
  });

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }

  function icon(id, cls) {
    if (id) {
      var src = icons[id] || "assets/textures/item/_placeholder.png";
      var label = names[id] || id;
      var frames = (T.spriteMeta || {})[src];
      if (frames && frames.length) {
        return '<span class="icon sprite ' + (cls || "") + '" data-sprite="' + frames.join("|") +
          '" data-frame="0" title="' + esc(label) + '">' +
          '<img src="' + frames[0] + '" alt="' + esc(label) + '"></span>';
      }
      return '<img class="icon ' + (cls || "") + '" src="' + src + '" alt="' + esc(label) + '" title="' + esc(label) + '">';
    }
    return '<span class="icon ' + (cls || "") + '" title="' + esc(id || "") + '"></span>';
  }

  /* one timer drives every sprite icon on the page; re-renders replace the DOM so nothing leaks */
  function startSpriteFlipper() {
    if (window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    setInterval(function () {
      var nodes = document.querySelectorAll("[data-sprite]");
      for (var i = 0; i < nodes.length; i++) {
        var node = nodes[i];
        var frames = node.getAttribute("data-sprite").split("|");
        var next = (parseInt(node.getAttribute("data-frame"), 10) + 1) % frames.length;
        node.setAttribute("data-frame", next);
        node.firstChild.src = frames[next];
      }
    }, 500);
  }

  function iconForRef(ref, cls) {
    if (!ref) return "";
    if (ref.id) {
      return icon(ref.id, cls) + "<span>" + esc(names[ref.id] || ref.id) + "</span>";
    }
    return '<span class="tag">#' + esc(String(ref.tag || "").replace(/^[a-z]+:/, "")) + "</span>";
  }

  function ingChip(ref) {
    return '<span class="ing">' + iconForRef(ref) + "</span>";
  }

  function rarityChip(rarity) {
    return '<span class="chip rarity-' + esc(rarity) + '">' + esc(String(rarity).replace(/_/g, " ")) + "</span>";
  }

  function titleize(s) {
    return String(s || "").replace(/[_.]/g, " ").replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }

  function pad(n) { return (n < 10 ? "0" : "") + n; }

  function fmtTick(ticks) {
    var t = ((Math.round(ticks) % 24000) + 24000) % 24000;
    var minutes = Math.round(t / 24000 * 1440) % 1440;
    return pad(Math.floor(minutes / 60)) + ":" + pad(minutes % 60);
  }

  function timeWindow(range) {
    return fmtTick(range.min) + " - " + fmtTick(range.max);
  }

  function pct(value) {
    if (value === null || value === undefined) return "-";
    return value >= 1 ? value.toFixed(2) + "%" : value.toFixed(3) + "%";
  }

  /* mod-internal temperature (0..1) -> the °C the Climate Gauge shows */
  function toC(mc) {
    return Math.round((11 * Math.pow(mc - 0.23, 3) + 30 * mc + 15) * 10) / 10;
  }

  /* the hook clamps the sampled reading to -1..1, so the reachable window does too */
  function tempEdge(mc) {
    return Math.max(-1, Math.min(1, mc));
  }

  /* Vanilla biome climate temperatures. The Climate sampler reads the same value the biome
     defines, and every ocean biome shares 0.5, which is why a deep-ocean gate can pin a
     temperature-sensitive fish to the very edge of its own range. Only verified values
     are listed - an unknown biome produces no warning rather than a wrong one. */
  var BIOME_TEMP = [
    [/deep (cold |lukewarm )?ocean/, 0.5, ""],
    [/frozen ocean/, -0.5, ""],
    [/cold ocean/, 0.5, ""],
    [/warm ocean/, 0.5, ""],
    [/ocean/, 0.5, ""],
    [/river/, 0.5, ""],
    [/dripstone caves/, 0.5, ""],
    [/deep dark/, 0.8, ""],
    [/stony shore/, 0.2, ""],
    [/jungle/, 0.95, ""],
    [/savanna|badlands/, 2.0, ""],
    [/desert/, 2.0, ""],
    [/swamp|bayou|bog|marsh/, 0.8, ""],
    [/snow|frozen|ice spikes|igloo/, -0.5, ""],
    [/taiga|old growth|tundra/, -0.5, ""],
    [/cherry grove|meadow|windswept hills/, 0.5, ""],
    [/plains|forest|groves?|sunflower/, 0.8, ""]
  ];

  function biomeTemp(name) {
    var lower = name.toLowerCase();
    for (var i = 0; i < BIOME_TEMP.length; i++) {
      if (BIOME_TEMP[i][0].test(lower)) return { temp: BIOME_TEMP[i][1], note: BIOME_TEMP[i][2] };
    }
    return null;
  }

  function tempFactor(temp, t) {
    return Math.max(0, 1 - Math.pow((temp - t.preferred) / t.tolerance, 2));
  }

  /* A biome gate whose own temperature is outside the fish's window: the fish can be
     caught there only after a hook moves the reading. */
  function biomeTempWarning(f) {
    if (!f.temperature) return null;
    var t = f.temperature;
    var known = [];
    (f.biomes || []).forEach(function (name) {
      var b = biomeTemp(name);
      if (b) known.push({ name: name, temp: b.temp, note: b.note, factor: tempFactor(b.temp, t) });
    });
    if (!known.length) return null;
    var dead = known.filter(function (b) { return b.factor === 0; });
    var weak = known.filter(function (b) { return b.factor > 0 && b.factor < 0.5; });
    if (!dead.length && !weak.length) return null;

    var worst = (dead.length ? dead : weak);
    var names = worst.map(function (b) { return b.name; }).join(", ");
    var first = worst[0];
    var shift = first.temp > t.preferred ? "Permafrost" : "Fiery";
    return names + " is the only biome that spawns this fish, and it reads " +
      toC(tempEdge(first.temp)).toFixed(1) + " °C against a preferred " +
      toC(t.preferred).toFixed(1) + " °C, which leaves the weight at " +
      (dead.length ? "zero" : (first.factor * 100).toFixed(0) + "%") + ". " +
      (dead.length ? "It cannot be caught in its own biome without a " + shift + " Hook to bring the reading " +
        "back onto the range." : "Expect a weak bite until you fit a " + shift + " Hook.");
  }

  function tagTitle(tag) {
    var map = {
      fishing_rods: "Fishing Rods", lava_fishing_rods: "Lava Fishing Rods", lines: "Lines",
      hooks: "Hooks", bobbers: "Bobbers", bait_items: "Bait", informational: "Information",
      crates: "Crates", fish: "Fish", vanilla_fish: "Vanilla Fish", cat_food: "Cat Food",
      lava_buckets: "Lava Buckets", cooked_fish: "Cooked Fish", cookable_fish: "Cookable Fish",
      luck_boosting_rods: "Luck Boosting Rods"
    };
    return map[tag] || titleize(tag);
  }

  /* ------------------------------------------------------------ state */

  var state = { fishQuery: "", fishGroup: "all", fishRarity: "all", fishPage: 0, itemQuery: "" };

  var NAV = [
    { hash: "#/", label: "Overview" },
    { hash: "#/fish", label: "Fish", group: true },
    { hash: "#/loadout", label: "Loadout planner", group: true },
    { hash: "#/items", label: "Items", group: true },
    { hash: "#/blocks", label: "Blocks", group: true },
    { hash: "#/recipes", label: "Recipes", group: true },
    { hash: "#/crates", label: "Crates & Loot" },
    { hash: "#/minigame", label: "Minigame" },
    { hash: "#/stats", label: "Stats & formulas", group: true },
    { hash: "#/config", label: "Config" },
    { hash: "#/commands", label: "Commands" },
    { hash: "#/advancements", label: "Advancements" },
    { hash: "#/compat", label: "Compatibility" }
  ];

  /* ------------------------------------------------------------ pages */

  function pageOverview() {
    var s = T.stats, m = T.meta;
    var rar = Object.keys(s.rarities).map(function (r) {
      return rarityChip(r) + " <span class='muted'>" + s.rarities[r] + "</span>";
    }).join(" &nbsp; ");

    var features = [
      ["Fishing journal", "Track every fish you catch. " + s.fish + " new fish across " +
        Object.keys(s.groups).length + " environments, plus the " + T.vanillaFish.length +
        " vanilla fish that get journal entries. " + esc(X.toastNewFish) + " toasts on new entries."],
      ["Fishing minigame", "Every hooked fish runs a catch minigame. Fish speed and strength set the difficulty; " +
        "lines and the difficulty multiplier tune it. Ratings: " +
        Object.keys(X.minigameFeedback).map(function (k) { return X.minigameFeedback[k]; }).join(", ") + "."],
      ["Gear", s.items + " items: rods, lines, hooks, bobbers and baits. Rods carry bonus behaviour, " +
        "lines change catch difficulty and luck, hooks change which fluids you can fish."],
      ["Crates", s.crates + " loot crates plus " + T.fishingLoot.length +
        " fishing loot tables (junk, treasure, bonuses). Reel in a crate instead of a fish for bonus items."],
      ["Blocks", s.blocks + " blocks including the Angling Table (rod upgrades), Fish Displays and three crate blocks."],
      ["Extra fluids", "Lava and a fishable Void surface are both fishable with the right rod and hook. " +
        s.groups.lava + " lava fish, " + s.groups.void + " void fish."],
      ["Fish sizes", "Caught fish get a randomised length. Small, typical and large fish cook into different items."],
      ["Compatibility", T.compat.length + " supported mods, including other fishing mods whose fish are merged in."]
    ];

    return '' +
      '<div class="hero">' +
      '<img src="' + m.icon + '" alt="">' +
      '<div><h1>' + esc(m.name) + ' <span class="muted small">v' + esc(m.version) + '</span></h1>' +
      '<p>' + esc(m.description) + '</p>' +
      '<div class="tag">Minecraft ' + esc(m.minecraft) + ' &middot; Fabric &middot; by ' + esc(m.author) +
      ' &middot; ' + esc(m.license) + ' &middot; requires ' + esc(m.depends.filter(function (d) { return d !== "minecraft"; }).join(", ")) + '</div></div></div>' +

      '<div class="stats">' +
      stat(s.fish, "fish") + stat(s.recipes, "recipes") + stat(s.items, "items") +
      stat(s.blocks, "blocks") + stat(s.crates, "crates") + stat(s.baits + s.lines, "baits + lines") +
      stat(s.advancements, "advancements") + stat(s.textures, "textures") +
      '</div>' +

      '<h2>What Tide adds</h2><div class="cards">' +
      features.map(function (f) {
        return '<div class="card"><div class="body"><div class="name">' + esc(f[0]) + '</div><div class="lines">' + f[1] + '</div></div></div>';
      }).join("") + '</div>' +

      '<h2>Fish by environment</h2><table><tr><th>Environment</th><th class="num">Fish</th></tr>' +
      Object.keys(s.groups).map(function (g) {
        return "<tr><td>" + esc(titleize(g)) + '</td><td class="num">' + s.groups[g] + "</td></tr>";
      }).join("") + "</table>" +

      '<h2>Rarity spread</h2><p>' + rar + '</p>' +

      '<h2>Using this wiki</h2>' +
      '<div class="note"><strong>Everything here is generated from the mod files</strong> of ' +
      esc(m.name) + ' ' + esc(m.version) + '. Fish spawn conditions, sizes, weights and recipes are read straight ' +
      'from the mod data, and every icon is the real in-game texture. If you update the mod, regenerate with ' +
      '<code>python tools/extract.py</code>.</div>' +

      '<h2>Links</h2><ul>' +
      '<li><a href="' + esc(m.homepage) + '">' + esc(m.homepage) + '</a></li>' +
      '<li><a href="' + esc(m.issues) + '">' + esc(m.issues) + '</a></li></ul>' +
      footer();
  }

  function stat(value, label) {
    return '<div class="stat"><b>' + value + '</b><span>' + esc(label) + '</span></div>';
  }

  function footer() {
    return '<footer>' + esc(T.meta.name) + " " + esc(T.meta.version) +
      " &middot; wiki generated from the mod jar &middot; data is authoritative, prose is not.</footer>";
  }

  /* ------------------------------------------------------------ fish */

  function fishCard(f) {
    return '<a class="card clickable" href="#/fish/' + esc(f.id) + '" style="text-decoration:none;color:inherit">' +
      icon(f.id) +
      '<div class="body"><div class="name">' + esc(f.name) + "</div>" +
      '<div class="meta">' + esc(f.location) + "</div>" +
      '<span class="chip">' + esc(f.groupName) + "</span>" + rarityChip(f.rarity) +
      (f.shiny ? '<span class="chip">shiny</span>' : "") +
      "</div></a>";
  }

  function filteredFish() {
    var q = state.fishQuery.toLowerCase();
    return T.fish.filter(function (f) {
      if (state.fishGroup !== "all" && f.group !== state.fishGroup) return false;
      if (state.fishRarity !== "all" && f.rarity !== state.fishRarity) return false;
      if (!q) return true;
      return (f.name + " " + f.location + " " + f.where.join(" ") + " " + f.biomes.join(" ")).toLowerCase().indexOf(q) >= 0;
    });
  }

  function pageFish() {
    var list = filteredFish();
    var pages = Math.max(1, Math.ceil(list.length / PER_PAGE));
    state.fishPage = Math.min(state.fishPage, pages - 1);
    var slice = list.slice(state.fishPage * PER_PAGE, state.fishPage * PER_PAGE + PER_PAGE);

    var groupChips = ["all"].concat(Object.keys(T.stats.groups)).map(function (g) {
      return '<button data-filter="group" data-value="' + g + '" class="' + (state.fishGroup === g ? "on" : "") + '">' +
        esc(g === "all" ? "All" : titleize(g)) + "</button>";
    }).join("");

    var rarities = ["all", "common", "uncommon", "rare", "very_rare", "legendary"].filter(function (r) {
      return r === "all" || T.stats.rarities[r];
    }).map(function (r) {
      return '<button data-filter="rarity" data-value="' + r + '" class="' + (state.fishRarity === r ? "on" : "") + '">' +
        esc(r === "all" ? "Any rarity" : titleize(r)) + "</button>";
    }).join("");

    return '' +
      "<h1>Fish</h1><p class=\"sub\">" + T.stats.fish + " fish. " +
      (T.vanillaFish.length ? T.vanillaFish.length + " vanilla fish also get journal entries and are listed at the bottom." : "") +
      '</p>' +
      '<div class="controls">' +
      '<input type="search" id="fishSearch" placeholder="Search fish, biomes, dimensions..." value="' + esc(state.fishQuery) + '">' +
      groupChips + rarities + "</div>" +
      '<p class="muted small">' + list.length + " of " + T.stats.fish + " fish shown.</p>" +
      '<div class="cards">' + slice.map(fishCard).join("") + "</div>" +
      pager(state.fishPage, pages, "fishPage") +
      '<h2>Vanilla fish</h2><div class="cards">' +
      T.vanillaFish.map(function (f) {
        return '<div class="card"><div class="body"><div class="name">' + esc(f.name) + '</div><div class="lines">' + esc(f.description) + "</div></div></div>";
      }).join("") + "</div>" +
      footer();
  }

  function pager(page, pages, key) {
    if (pages <= 1) return "";
    return '<div class="pager">' +
      '<button data-pagekey="' + key + '" data-value="' + (page - 1) + '"' + (page === 0 ? " disabled" : "") + ">Previous</button>" +
      '<span class="muted small">Page ' + (page + 1) + " of " + pages + "</span>" +
      '<button data-pagekey="' + key + '" data-value="' + (page + 1) + '"' + (page === pages - 1 ? " disabled" : "") + ">Next</button></div>";
  }

  function pageFishDetail(id) {
    var f = T.fish.filter(function (x) { return x.id === id; })[0];
    if (!f) return "<h1>Fish not found</h1><p><a href=\"#/fish\">Back to the fish list</a></p>";

    var record = f.size.record || f.size.high || 1;
    var left = (f.size.low / record) * 100;
    var width = ((f.size.high - f.size.low) / record) * 100;
    var bar = f.size.low ? '<div class="bar"><div class="range" style="left:' + left.toFixed(1) + "%;width:" + width.toFixed(1) + '%"></div>' +
      '<div class="record" style="left:100%"></div></div>' +
      '<div class="labels"><span>typical ' + f.size.low + " cm</span><span>" + f.size.high + " cm</span><span>record " + f.size.record + " cm</span></div>" : "";

    var stats = [];
    [["Speed", f.speed], ["Strength", f.strength], ["Selection weight", f.weight],
     ["Selection quality", f.quality], ["Behaviour", f.behavior], ["Size class", sizeClass(f)],
     ["Cooks into", f.cookTier ? f.cookTier.replace(/_/g, " ") : null],
     ["Median size", f.sizeStats ? f.sizeStats.p50 + " cm" : null],
     ["Luck needed", f.luckGate],
     ["Bucket", f.bucket ? names[f.bucket] || f.bucket : null]].forEach(function (row) {
      if (row[1] === null || row[1] === undefined || row[1] === "") return;
      stats.push("<tr><th>" + esc(row[0]) + '</th><td class="mono">' + esc(row[1]) + "</td></tr>");
    });

    var odds = f.weightsAtLuck ? "<table><tr><th>Luck</th>" +
      Object.keys(f.weightsAtLuck).map(function (k) { return '<th class="num">' + k + "</th>"; }).join("") +
      "</tr><tr><td>Weight</td>" + Object.keys(f.weightsAtLuck).map(function (k) {
        return '<td class="num mono">' + f.weightsAtLuck[k] + "</td>"; }).join("") +
      "</tr><tr><td>Share of pool</td>" + Object.keys(f.shareAtLuck).map(function (k) {
        return '<td class="num mono">' + pct(f.shareAtLuck[k]) + "</td>"; }).join("") +
      "</tr></table>" : "";

    var related = T.recipes.filter(function (r) {
      var stem = f.id.split(":")[1];
      var hay = [r.result.id].concat((r.ingredients || []).map(function (x) { return x.id || x.tag; }),
        (r.base || []).map(function (x) { return x.id || x.tag; }),
        r.ingredient ? [r.ingredient.id || r.ingredient.tag] : []);
      return hay.some(function (x) { return x && (x === f.id || (x.indexOf(stem) >= 0 && x.indexOf("tide:" + stem) === 0)); });
    }).slice(0, 8);

    return '<div class="crumbs"><a href="#/fish">&larr; All fish</a></div>' +
      '<div class="hero">' + icon(f.id, "lg") +
      '<div><h1>' + esc(f.name) + "</h1>" +
      '<span class="chip">' + esc(f.groupName) + "</span>" + rarityChip(f.rarity) +
      '<span class="chip">' + esc(f.location) + "</span>" +
      (f.shiny ? '<span class="chip">shiny variant</span>' : "") +
      '<p style="margin-top:8px">' + esc(f.description) + "</p>" +
      '<p><a href="#/loadout/' + esc(f.id) + '">Plan a loadout for this fish &rarr;</a></p></div></div>' +

      "<h2>Where to find it</h2>" +
      (f.where.length ? "<ul>" + f.where.map(function (w) { return "<li>" + esc(w) + "</li>"; }).join("") + "</ul>"
        : '<p class="muted">No special conditions - it shows up wherever Tide spawns ordinary ' + esc(f.groupName.toLowerCase()) + " fish.</p>") +
      biomeFactsNote(f) +
      (biomeTempWarning(f) ? '<div class="note"><strong>Temperature trap.</strong> ' + esc(biomeTempWarning(f)) + "</div>" : "") +

      "<h2>Size</h2>" + bar +
      '<p class="muted small">Records are tracked per fish. Bigger fish cook into bigger meals.</p>' +

      "<h2>Fishing data</h2><table>" + stats.join("") + "</table>" +

      (odds ? "<h2>Odds</h2>" + odds +
        '<p class="muted small">Share is measured against the ' + f.pool +
        " fish sharing this fish's medium and dimension.</p>" : "") +

      (related.length ? "<h2>Related recipes</h2>" + related.map(recipeCard).join("") : "") +
      footer();
  }

  function biomeFactsNote(f) {
    var parts = [];
    if ((f.biomeTags || []).length) {
      parts.push("<strong>Tagged biomes.</strong> " + f.biomeTags.map(function (t) {
        return esc(t.replace(/^#/, ""));
      }).join(", ") + (f.biomeTags.length > 1 ? " are" : " is") +
        " a biome tag, not a single biome: the fish spawns in any biome the tag covers.");
    }
    if ((f.modBiomes || []).length) {
      parts.push("<strong>Needs another mod.</strong> " + esc(f.modBiomes.join(", ")) +
        " only exist if the mod that adds them is installed, so this fish gets harder to find without it.");
    }
    return parts.length ? '<div class="note">' + parts.join(" ") + "</div>" : "";
  }

  function sizeClass(f) {
    var s = f.size;
    if (!s.low) return null;
    if (s.record && s.high >= s.record * 0.95) return "record";
    if (s.low < 30) return "small";
    if (s.high > 60) return "large";
    return "typical";
  }

  /* ------------------------------------------------------------ items */

  var ITEM_SECTIONS = [
    { title: "Fishing rods", match: function (i) { return i.tags.indexOf("fishing_rods") >= 0 || i.tags.indexOf("lava_fishing_rods") >= 0; } },
    { title: "Lines", match: function (i) { return i.tags.indexOf("lines") >= 0; } },
    { title: "Hooks", match: function (i) { return i.tags.indexOf("hooks") >= 0; } },
    { title: "Bobbers", match: function (i) { return i.tags.indexOf("bobbers") >= 0; } },
    { title: "Bait", match: function (i) { return T.baits.some(function (b) { return b.item === i.id; }); } },
    { title: "Tools & information", match: function (i) { return i.tags.indexOf("informational") >= 0 || i.id === "tide:fish_finder" || i.id === "tide:climate_gauge" || i.id === "tide:depth_meter" || i.id === "tide:pocket_watch" || i.id === "tide:enchanted_pocket_watch" || i.id === "tide:weather_radio" || i.id === "tide:lunar_calendar" || i.id === "tide:fish_satchel" || i.id === "tide:fishing_journal" || i.id === "tide:fishy_note"; } },
    { title: "Fish and buckets", match: function (i) { return i.isFish; } },
    { title: "Crates", match: function (i) { return i.tags.indexOf("crates") >= 0; } }
  ];

  function pageItems() {
    var q = state.itemQuery.toLowerCase();
    var used = {};
    var html = "<h1>Items</h1><p class=\"sub\">" + T.stats.items +
      " items Tide knows about, grouped by role. Descriptions are the real in-game tooltips.</p>" +
      '<div class="controls"><input type="search" id="itemSearch" placeholder="Search items..." value="' + esc(state.itemQuery) + '"></div>';

    ITEM_SECTIONS.forEach(function (section) {
      var list = T.items.filter(section.match).filter(function (i) {
        used[i.id] = true;
        return !q || (i.name + " " + i.id + " " + i.desc.join(" ")).toLowerCase().indexOf(q) >= 0;
      });
      if (!list.length) return;
      html += "<h2>" + esc(section.title) + ' <span class="muted small">(' + list.length + ")</span></h2>";
      html += list.length > 8 ? '<div class="cards">' + list.map(itemCard).join("") + "</div>" :
        "<table>" + list.map(itemRow).join("") + "</table>";
    });

    var rest = T.items.filter(function (i) { return !used[i.id]; }).filter(function (i) {
      return !q || (i.name + " " + i.id).toLowerCase().indexOf(q) >= 0;
    });
    if (rest.length) {
      html += '<h2>Other <span class="muted small">(' + rest.length + ")</span></h2><div class=\"cards\">" +
        rest.map(itemCard).join("") + "</div>";
    }

    html += "<h2>Rod bonuses</h2><table><tr><th>Rod</th><th>Bonus</th></tr>" +
      T.rodBonuses.map(function (b) { return "<tr><td>" + esc(b.key) + "</td><td>" + esc(b.text) + "</td></tr>"; }).join("") +
      "</table>";

    html += "<h2>Bait effects</h2>" +
      '<div class="note">' + esc(X.baitPrefix) + " bait is applied from a rod's bait slot (" + esc(X.baitSlotDesc) + ").</div>" +
      "<table><tr><th>Bait</th><th class=\"num\">Fishing luck</th><th class=\"num\">Fishing speed</th></tr>" +
      T.baits.map(function (b) {
        return "<tr><td>" + iconForRef({ id: b.item }) + "</td><td class=\"num\">" +
          (b.luck ? "+" + b.luck : "-") + '</td><td class="num">' + (b.speed ? "+" + b.speed : "-") + "</td></tr>";
      }).join("") + "</table>" + footer();
    return html;
  }

  function itemCard(i) {
    return '<div class="card">' + icon(i.id) + '<div class="body"><div class="name">' + esc(i.name) + "</div>" +
      '<div class="meta mono">' + esc(i.id) + "</div>" +
      (i.desc.length ? '<div class="lines">' + i.desc.map(esc).join("<br>") + "</div>" : "") + "</div></div>";
  }

  function itemRow(i) {
    return "<tr><td>" + icon(i.id, "sm") + " " + esc(i.name) + '</td><td class="mono small">' + esc(i.id) + "</td><td>" +
      i.desc.map(esc).join("<br>") + "</td></tr>";
  }

  /* ------------------------------------------------------------ blocks */

  function pageBlocks() {
    return "<h1>Blocks</h1><p class=\"sub\">" + T.stats.blocks + " blocks.</p>" +
      '<div class="cards">' + T.blocks.map(function (b) {
        return '<div class="card">' + icon(b.id) + '<div class="body"><div class="name">' + esc(b.name) + "</div>" +
          '<div class="meta mono">' + esc(b.id) + "</div>" +
          (b.desc.length ? '<div class="lines">' + b.desc.map(esc).join("<br>") + "</div>" : "") + "</div></div>";
      }).join("") + "</div>" +
      '<h2>What they do</h2>' +
      "<ul>" +
      "<li><strong>Angling Table</strong> - the rod upgrade bench. Rods are smithed, but the table applies Tide's rod line and bait rules.</li>" +
      "<li><strong>Fish Display</strong> - mounts a caught fish on a wall, in three sizes.</li>" +
      "<li><strong>Crates</strong> (Wooden, Purpur, Obsidian) - placeable loot crates that roll the crate tables on the <a href=\"#/crates\">Crates page</a>.</li>" +
      "<li><strong>Jelly Torch</strong> - lights that can be placed underwater.</li>" +
      "<li><strong>Lunar Calendar</strong> and <strong>Weather Radio</strong> - information blocks; their readings feed the journal and your HUD.</li>" +
      "</ul>" + footer();
  }

  /* ------------------------------------------------------------ recipes */

  var CATEGORY_ORDER = ["equipment", "misc", "food", "combat", "decorations", "building_blocks"];
  var recipeCat = "all";

  function pageRecipes() {
    var cats = CATEGORY_ORDER.filter(function (c) { return T.recipes.some(function (r) { return r.category === c; }); });
    Object.keys(T.recipes.reduce(function (acc, r) { acc[r.category] = 1; return acc; }, {})).forEach(function (c) {
      if (cats.indexOf(c) < 0) cats.push(c);
    });
    var chips = ["all"].concat(cats).map(function (c) {
      return '<button data-cat="' + c + '" class="' + (recipeCat === c ? "on" : "") + '">' +
        esc(c === "all" ? "All" : titleize(c)) + "</button>";
    }).join("");
    var list = T.recipes.filter(function (r) { return recipeCat === "all" || r.category === recipeCat; });

    return "<h1>Recipes</h1><p class=\"sub\">" + T.stats.recipes + ' recipes. Crafting tags come from the Fabric tag library, so "' +
      '#c:ingots/iron' + '" means any mod can add iron ingots.</p>' +
      '<div class="controls">' + chips + "</div>" +
      list.map(recipeCard).join("") + footer();
  }

  function recipeCard(r) {
    var out = icon(r.result.id) + '<div><div class="name">' + esc(r.resultName) + "</div>" +
      '<div class="meta">' + esc(r.type.replace("minecraft:", "").replace("tide:", "")) +
      (r.count > 1 ? ' &middot; x' + r.count : "") + "</div></div>";

    var body = "";
    if (r.pattern) {
      body = '<div class="grid-recipe" style="grid-template-columns:repeat(' + r.pattern[0].length + ',38px)">';
      r.pattern.forEach(function (row) {
        row.split("").forEach(function (sym) {
          var ref = sym === " " ? null : r.key[sym];
          var inner = "";
          if (ref && ref.id && icons[ref.id]) {
            inner = '<img src="' + icons[ref.id] + '" alt="' + esc(names[ref.id] || ref.id) + '">';
          } else if (ref) {
            inner = "<span class=\"sym\">" + esc(sym) + "</span>";
          }
          body += '<div class="cell" title="' + esc(ref ? (names[ref.id] || ref.tag || ref.id) : "") + '">' + inner + "</div>";
        });
      });
      body += "</div>";
      var legend = Object.keys(r.key).map(function (sym) { return "<span class='ing'>" + sym + " " + iconForRef(r.key[sym]) + "</span>"; }).join("");
      body += '<div class="ingredients">' + legend + "</div>";
    } else if (r.ingredients) {
      body = '<div class="ingredients">' + r.ingredients.map(ingChip).join("") + "</div>";
    } else if (r.base) {
      body = '<div class="small muted">' + esc(titleize(r.type.replace("minecraft:", ""))) + "</div>" +
        '<div class="ingredients">' + r.base.map(ingChip).join("") + ingChip(r.template) + ingChip(r.addition) + "</div>";
    } else if (r.ingredient) {
      body = '<div class="ingredients">' + ingChip(r.ingredient) + "</div>" +
        '<div class="small muted">' + (r.time ? (r.time / 20) + "s" : "") + (r.xp ? " &middot; " + r.xp + " XP" : "") + "</div>";
    } else if (r.special) {
      body = '<div class="small muted">' + esc(r.special) + "</div>";
    }

    return '<div class="recipe"><div class="out">' + out + '</div><div class="in">' + body + "</div></div>";
  }

  /* ------------------------------------------------------------ crates */

  function pageCrates() {
    function table(t) {
      return '<h2>' + esc(t.name) + "</h2>" + t.pools.map(function (pool) {
        return '<p class="small muted">' + (pool.rolls ? "Rolls " + pool.rolls + " entries" : "Rolls 1 entry") + "</p>" +
          "<table><tr><th>Item</th><th class=\"num\">Weight</th><th class=\"num\">Chance</th><th class=\"num\">Count</th><th>Notes</th></tr>" +
          pool.entries.map(function (e) {
            var note = [];
            if (e.enchanted) note.push("enchanted");
            if (e.quality) note.push("luck quality " + e.quality);
            return "<tr><td>" + iconForRef({ id: e.id }) + "</td><td class=\"num\">" + e.weight +
              '</td><td class="num">' + (e.chance ? Math.round(e.chance * 100) + "%" : "-") +
              '</td><td class="num">' + (e.count > 1 ? e.count : "-") + "</td><td class=\"small muted\">" + esc(note.join(", ")) + "</td></tr>";
          }).join("") + "</table>";
      }).join("");
    }

    var crateOpts = configOptions("server", "general");
    return "<h1>Crates &amp; loot</h1>" +
      '<p class="sub">Fishing can pull a crate instead of a fish. Crates also exist as placeable blocks.</p>' +
      '<div class="note">Crate chance is controlled by <strong>' + esc(titleize(crateOpts.crateWeight)) + "</strong> (default " +
      esc(String(crateOpts.crateWeight_value)) + ") and scales with luck via <strong>" +
      esc(titleize(crateOpts.crateQuality)) + "</strong> (default " + esc(String(crateOpts.crateQuality_value)) +
      "). " + esc(crateOpts.crateWeight_tip || "") + "</div>" +
      T.crates.map(table).join("") +
      "<h2>Fishing loot tables</h2>" +
      '<p class="muted small">These roll for ordinary catches instead of a fish entry.</p>' +
      T.fishingLoot.map(table).join("") + footer();
  }

  function configOptions(side, cat) {
    var out = {};
    ((T.config[side] || []).filter(function (c) { return c.key === cat; })[0] || { options: [] }).options.forEach(function (o) {
      out[o.key] = o.name;
      out[o.key + "_value"] = o.default;
      out[o.key + "_tip"] = o.tooltip;
    });
    return out;
  }

  /* ------------------------------------------------------------ minigame */

  function pageMinigame() {
    var opts = ((T.config.server || []).filter(function (c) { return c.key === "minigame"; })[0] || { options: [] }).options;
    var client = ((T.config.client || []).filter(function (c) { return c.key === "minigame"; })[0] || { options: [] }).options;
    var difficulty = T.lines.filter(function (l) {
      return (l.desc || []).join(" ").toLowerCase().indexOf("difficulty") >= 0;
    });

    return "<h1>Catch minigame</h1>" +
      '<p class="sub">When a fish bites, Tide runs a catch minigame. Miss it and the fish escapes.</p>' +
      "<p>Minigame speed and difficulty come from the hooked fish's <strong>speed</strong> and " +
      "<strong>strength</strong> values, plus your gear. Faster or stronger fish are harder to land.</p>" +
      "<h2>Server options</h2>" + optionTable(opts) +
      "<h2>Client options</h2>" + optionTable(client) +
      "<h2>Difficulty modifiers</h2>" +
      '<div class="note">Lines can make the minigame easier. ' + esc(titleize(difficulty.map(function (l) { return l.name; }).join(", ") || "none")) + " lower catch difficulty.</div>" +
      "<table><tr><th>Accessory</th><th>Effect</th></tr>" +
      difficulty.map(function (l) { return "<tr><td>" + iconForRef({ id: l.item }) + "</td><td>" + l.desc.map(esc).join("<br>") + "</td></tr>"; }).join("") +
      "</table>" +
      "<h2>Feedback</h2>" +
      "<p>" + Object.keys(X.minigameFeedback).map(function (k) { return '<span class="chip">' + esc(X.minigameFeedback[k]) + "</span>"; }).join(" ") +
      ' <span class="muted small">Shown when a catch is graded. Disable server-side with "Do Feedback".</span></p>' +
      "<h2>Other fishing mods</h2>" +
      "<p>If Stardew Fishing or another mod provides its own minigame, Tide can use that instead and use that mod's fish " +
      "data (length, bucketability). Both are server options above.</p>" + footer();
  }

  /* ------------------------------------------------------------ config */

  function optionTable(options) {
    if (!options || !options.length) return '<p class="muted">None.</p>';
    return "<table><tr><th>Option</th><th>Current value</th><th>What it does</th></tr>" +
      options.map(function (o) {
        return "<tr><td>" + esc(o.name) + '<div class="mono small muted">' + esc(o.key) + "</div></td>" +
          '<td class="mono">' + esc(String(o.default)) + "</td><td>" + esc(o.tooltip || "") + "</td></tr>";
      }).join("") + "</table>";
  }

  function pageConfig() {
    function side(sideKey, title) {
      var cats = T.config[sideKey] || [];
      return "<h2>" + title + "</h2>" + cats.map(function (c) {
        return "<h3>" + esc(c.name) + "</h3>" + optionTable(c.options);
      }).join("");
    }
    return "<h1>Config</h1>" +
      '<p class="sub">Tide uses Cloth Config. Settings live in <code>config/tide/</code> on the server (world) side.</p>' +
      '<div class="note">Values below come from the generated <code>tide_server.json</code> and ' +
      '<code>tide_client.json</code> of a default install. If a value was changed, this page shows the changed value.</div>' +
      side("server", "Server") + side("client", "Client") + footer();
  }

  /* ------------------------------------------------------------ commands */

  function pageCommands() {
    return "<h1>Commands</h1><p class=\"sub\">Two debug/admin commands, both require operator permission.</p>" +
      T.commands.map(function (c) {
        return "<h2>" + esc(c.name) + "</h2><p><code>" + esc(c.usage) + "</code></p><p>" + esc(c.desc) + "</p>" +
          "<table><tr><th>Message</th><th>Text</th></tr>" +
          c.strings.map(function (s) {
            return '<tr><td class="mono small">' + esc(s.key) + "</td><td>" + esc(s.text) + "</td></tr>";
          }).join("") + "</table>";
      }).join("") + footer();
  }

  /* ------------------------------------------------------------ advancements */

  function pageAdvancements() {
    var byId = {};
    T.advancements.forEach(function (a) { byId[a.id] = a; });
    return "<h1>Advancements</h1><p class=\"sub\">" + T.stats.advancements + ' advancements. The root ("Tide") triggers when you get any fishing rod.</p>' +
      '<div class="cards">' + T.advancements.map(function (a) {
        return '<div class="card">' + (a.icon ? icon(a.id) : "") +
          '<div class="body"><div class="name">' + esc(a.title) + '</div><div class="lines">' + esc(a.description) + "</div>" +
          (a.parent && byId[a.parent] ? '<div class="meta">after "' + esc(byId[a.parent].title) + '"</div>' : "") + "</div></div>";
      }).join("") + "</div>" + footer();
  }

  /* ------------------------------------------------------------ compat */

  function pageCompat() {
    return "<h1>Compatibility</h1>" +
      '<p class="sub">Tide reads fish and loot from several other mods and converts between fishing systems.</p>' +
      "<table><tr><th>Mod</th><th>Integration</th></tr>" +
      T.compat.map(function (c) {
        return "<tr><td>" + esc(c.name) + "</td><td>" + esc(c.note) + "</td></tr>";
      }).join("") + "</table>" +
      '<div class="note">Other fishing mods merge their fish into the journal. Tide also ships its own data for ' +
      "Hybrid Aquatic and Nether Depths Upgrade fish, so they are registered even when those mods are not installed " +
      "(their loot and behaviour still comes from the other mod).</div>" + footer();
  }

  /* ------------------------------------------------------------ stats */

  function pageStats() {
    var M = T.mechanics;
    var qualityFish = T.fish.filter(function (f) { return f.quality; });
    var gatedFish = T.fish.filter(function (f) { return f.luckGate; });
    var behaviors = {};
    T.fish.forEach(function (f) {
      if (!f.behavior) return;
      (behaviors[f.behavior] = behaviors[f.behavior] || []).push(f);
    });
    var strongest = T.fish.filter(function (f) { return typeof f.strength === "number"; })
      .sort(function (a, b) { return b.strength - a.strength; }).slice(0, 12);
    var fastest = T.fish.filter(function (f) { return typeof f.speed === "number"; })
      .sort(function (a, b) { return b.speed - a.speed; }).slice(0, 12);
    var tempered = T.fish.filter(function (f) { return f.temperature; });
    var coel = T.fish.filter(function (f) { return f.name === "Coelacanth"; })[0];
    var lineRows = T.lines.map(function (l) {
      var e = l.effects || {};
      return "<tr><td>" + iconForRef({ id: l.item }) + "</td><td class=\"mono\">" +
        (e.speed ? "speed x" + e.speed : "-") + "</td><td class=\"mono\">" +
        (e.strength ? "strength x" + e.strength : "-") + "</td><td class=\"mono\">" +
        (e.luck ? "+" + e.luck + " luck" : "-") + "</td></tr>";
    }).join("");

    var luckCols = Object.keys(coel ? coel.weightsAtLuck : {});
    var example = coel ? "<table><tr><th>Luck</th>" + luckCols.map(function (l) { return "<th class=\"num\">" + l + "</th>"; }).join("") +
      "</tr><tr><td>Weight</td>" + luckCols.map(function (l) { return '<td class="num mono">' + coel.weightsAtLuck[l] + "</td>"; }).join("") +
      "</tr><tr><td>Share of pool</td>" + luckCols.map(function (l) { return '<td class="num mono">' + pct(coel.shareAtLuck[l]) + "</td>"; }).join("") +
      "</tr></table><p class=\"muted small\">Coelacanth: selection_weight " + coel.weight +
      ", selection_quality " + coel.quality + ", pool of " + coel.pool + " eligible fish in its environment.</p>" : "";

    var behaviorRows = Object.keys(behaviors).sort(function (a, b) { return behaviors[b].length - behaviors[a].length; })
      .map(function (b) {
        return "<tr><td class=\"mono\">" + esc(b) + "</td><td class=\"num\">" + behaviors[b].length +
          '</td><td class="small">' + behaviors[b].slice(0, 6).map(function (f) {
            return '<a href="#/fish/' + esc(f.id) + '">' + esc(f.name) + "</a>";
          }).join(", ") + (behaviors[b].length > 6 ? ", ..." : "") + "</td></tr>";
      }).join("");

    var sizeRows = T.fish.slice().sort(function (a, b) { return (b.sizeStats ? b.sizeStats.p50 : 0) - (a.sizeStats ? a.sizeStats.p50 : 0); })
      .map(function (f) {
        var s = f.sizeStats || {};
        return "<tr><td><a href=\"#/fish/" + esc(f.id) + '">' + esc(f.name) + "</a></td>" +
          '<td class="num mono">' + (s.p10 || "-") + "</td><td class=\"num mono\">" + (s.p50 || "-") + "</td>" +
          '<td class="num mono">' + (s.p90 || "-") + "</td><td class=\"num mono\">" + (s.record || "-") + "</td>" +
          '<td class="small">' + (f.cookTier ? esc(f.cookTier.replace(/_/g, " ")) : "-") + "</td></tr>";
      }).join("");

    var tempRows = tempered.slice(0, 14).map(function (f) {
      var t = f.temperature;
      var at = function (temp) { var inner = Math.abs((temp - t.preferred) / t.tolerance); return Math.max(0, 1 - inner * inner); };
      return "<tr><td><a href=\"#/fish/" + esc(f.id) + '">' + esc(f.name) + "</a></td>" +
        '<td class="num mono">' + toC(t.preferred).toFixed(1) + " °C</td>" +
        '<td class="num mono">' + toC(tempEdge(t.preferred - t.tolerance)).toFixed(1) + "–" +
        toC(tempEdge(t.preferred + t.tolerance)).toFixed(1) + " °C</td>" +
        '<td class="num mono">' + (at(t.preferred) * 100).toFixed(0) + "%</td>" +
        '<td class="num mono">' + (at(tempEdge(t.preferred + t.tolerance)) * 100).toFixed(0) + "%</td>" +
        '<td class="num mono">' + (at(0) * 100).toFixed(0) + "%</td></tr>";
    }).join("");

    var lureRows = [0, 1, 2, 3, 4, 5].map(function (level) {
      var saved = Math.round(2000 / (1 + Math.exp(-0.2 * level)) - 1000);
      var base = 200 + (600 - 200) / 2;
      return "<tr><td class=\"num\">" + level + '</td><td class="num mono">-' + saved +
        '</td><td class="num mono">' + Math.round((base - saved) * M.mediumMultipliers.water) + "</td>" +
        '<td class="num mono">' + Math.round((base - saved) * M.mediumMultipliers.lava) + "</td>" +
        '<td class="num mono">' + Math.round((base - saved) * M.mediumMultipliers.void) + "</td></tr>";
    }).join("");

    var crateOpts = configOptions("server", "general");

    return "<h1>Stats &amp; formulas</h1>" +
      '<p class="sub">Every number Tide rolls, where it comes from, and what it does. Formulas are transcribed ' +
      "from the mod's public source (v2.1.1).</p>" +

      "<h2>How a catch is resolved</h2>" +
      "<ol><li><strong>Conditions</strong> - every condition must pass, or the fish is removed from the roll. " +
      "Examples: biome, fluid, depth, time, weather, moon phase, season, luck minimum.</li>" +
      "<li><strong>Modifiers</strong> - the survivors get their weight multiplied. Temperature uses a bell curve; " +
      "a badly wrong temperature drops the weight to zero and removes the fish.</li>" +
      "<li><strong>Weighted roll</strong> - a random number picks one entry proportionally to weight.</li>" +
      "<li><strong>Size roll</strong> - the caught fish gets a length, then the minigame is rolled against that fish's stats.</li></ol>" +

      "<h2>selection_weight and selection_quality</h2>" +
      '<div class="formula">' + esc(M.weightFormula) + "</div>" +
      '<p class="small muted">' + esc(M.weightSource) + "</p>" +
      "<p>" + esc(M.shareFormula) + ". " + esc(M.weightNote) + "</p>" +
      example +
      '<div class="note"><strong>' + esc(M.fishEntryFormula) + "</strong> " +
      "Every roll also contains a generic fish entry that competes with real fish. It carries no luck scaling, so " +
      "raising luck shifts probability away from it and toward the rare fish.</div>" +
      "<h3>Fish that scale with luck (" + qualityFish.length + " of " + T.stats.fish + ")</h3>" +
      "<p class=\"muted small\">All of them use the same 0.5 coefficient. The other " +
      (T.stats.fish - qualityFish.length) + " fish have a quality of 0 and never change with luck.</p>" +
      "<table><tr><th>Fish</th><th class=\"num\">Weight</th><th class=\"num\">Weight at luck 10</th><th class=\"num\">Share at luck 10</th></tr>" +
      qualityFish.map(function (f) {
        return '<tr><td><a href="#/fish/' + esc(f.id) + '">' + esc(f.name) + '</a> ' + rarityChip(f.rarity) + "</td>" +
          '<td class="num mono">' + f.weight + '</td><td class="num mono">' + f.weightsAtLuck["10"] +
          '</td><td class="num mono">' + pct(f.shareAtLuck["10"]) + "</td></tr>";
      }).join("") + "</table>" +

      "<h2>Conditions vs modifiers</h2>" +
      "<p>Conditions are yes/no gates. Modifiers scale the weight of a fish that already passed every gate. " +
      "The only modifier used by Tide's own fish is temperature:</p>" +
      '<div class="formula">' + esc(M.modifierFormula) + "</div>" +
      '<p class="small muted">' + esc(M.modifierSource) + "</p>" +
      "<p>Hooks shift the reading by a fixed amount of the internal 0..1 scale: Fiery adds 0.25, Permafrost takes " +
      "0.25 off. Because the Climate Gauge conversion is a cubic curve, that is worth anywhere from about 7 °C " +
      "near the middle of the scale to nearly 18 °C at the cold end, so the size of the nudge depends on where " +
      "you are standing. " + tempered.length + " fish are temperature sensitive.</p>" +
      "<table><tr><th>Fish</th><th class=\"num\">Preferred</th><th class=\"num\">Catchable range</th>" +
      "<th class=\"num\">Weight at preferred</th><th class=\"num\">At range edge</th><th class=\"num\">At neutral (" + toC(0).toFixed(1) + " °C)</th></tr>" +
      tempRows + "</table>" +

      "<h2>strength</h2>" +
      '<div class="formula">' + esc(M.minigameAreaFormula) + "</div>" +
      "<p>Strength is the share of the bar you are <em>not</em> allowed to be in. Higher strength means a smaller " +
      "hit area and a harder minigame. Defaults to 0.3 when unset.</p>" +
      "<table><tr><th>Fish</th><th class=\"num\">strength</th><th class=\"num\">Hit area</th><th class=\"num\">With Diamond Line</th></tr>" +
      strongest.map(function (f) {
        var area = Math.min(Math.max(1 - f.strength, 0.05), 1);
        return '<tr><td><a href="#/fish/' + esc(f.id) + '">' + esc(f.name) + "</a></td>" +
          '<td class="num mono">' + f.strength + '</td><td class="num mono">' + (area * 100).toFixed(1) + "%" +
          '</td><td class="num mono">' + (Math.min(Math.max(1 - f.strength * 0.75, 0.05), 1) * 100).toFixed(1) + "%</td></tr>";
      }).join("") + "</table>" +
      "<h3>Line modifiers</h3><table><tr><th>Line</th><th>Speed</th><th>Strength</th><th>Luck</th></tr>" + lineRows + "</table>" +
      '<p class="small muted">One line at a time. ' + esc(M.minigameSource) + "</p>" +

      "<h2>speed</h2>" +
      '<div class="formula">' + esc(M.minigameSpeedFormula) + "</div>" +
      "<p>Speed is how fast the fish crosses the bar, in movements per second. Defaults to 1.0 when unset.</p>" +
      "<table><tr><th>Fish</th><th class=\"num\">speed</th><th class=\"num\">Movements/s</th><th class=\"num\">With Copper Line</th></tr>" +
      fastest.map(function (f) {
        return '<tr><td><a href="#/fish/' + esc(f.id) + '">' + esc(f.name) + "</a></td>" +
          '<td class="num mono">' + f.speed + '</td><td class="num mono">' + (f.speed / 20).toFixed(2) +
          '</td><td class="num mono">' + (f.speed * 0.9 / 20).toFixed(2) + "</td></tr>";
      }).join("") + "</table>" +

      "<h2>behavior</h2>" +
      "<p>The curve the fish follows across the minigame bar. Six shapes are available.</p>" +
      "<table><tr><th>Behavior</th><th class=\"num\">Fish</th><th>Examples</th></tr>" + behaviorRows + "</table>" +

      "<h2>size</h2>" +
      "<p>" + esc(M.sizeFormula) + ". " + esc(M.sizeFloor) + ".</p>" +
      '<p class="small muted">' + esc(M.sizeSource) + "</p>" +
      "<table><tr><th>Fish</th><th class=\"num\">P10</th><th class=\"num\">Median</th><th class=\"num\">P90</th>" +
      "<th class=\"num\">Record</th><th>Cooks into</th></tr>" + sizeRows + "</table>" +

      "<h2>Luck</h2>" +
      "<h3>Where it comes from</h3><ul>" + M.luckSources.map(function (s) { return "<li>" + esc(s) + "</li>"; }).join("") + "</ul>" +
      '<p class="muted small">' + esc(M.sunflowerNote) + "</p>" +
      "<h3>What it changes</h3><ul>" + M.luckUses.map(function (s) { return "<li>" + esc(s) + "</li>"; }).join("") + "</ul>" +
      (gatedFish.length ? "<h3>Hard luck gates</h3><ul>" + gatedFish.map(function (f) {
        return '<li><a href="#/fish/' + esc(f.id) + '">' + esc(f.name) + "</a> needs luck " + f.luckGate + "</li>";
      }).join("") + "</ul>" : "") +

      "<h2>Crates</h2>" +
      '<div class="formula">' + esc(M.crateFormula) + "</div>" +
      '<p class="small muted">' + esc(M.crateSource) + "</p>" +
      "<p>Your instance runs crateWeight " + esc(String(crateOpts.crateWeight_value)) + " and crateQuality " +
      esc(String(crateOpts.crateQuality_value)) + ". " + esc(M.magneticBait) + "</p>" +
      "<table><tr><th>Luck</th><th class=\"num\">Crate weight</th><th class=\"num\">With Magnetic Bait</th></tr>" +
      [0, 2, 5, 10].map(function (luck) {
        var base = Number(crateOpts.crateWeight_value) + Number(crateOpts.crateQuality_value) * luck;
        return '<tr><td class="num">' + luck + '</td><td class="num mono">' + base.toFixed(1) +
          '</td><td class="num mono">' + (base * 5).toFixed(1) + "</td></tr>";
      }).join("") + "</table>" +

      "<h2>Bite timer</h2>" +
      '<div class="formula">' + esc(M.biteFormula) + "</div>" +
      '<p class="small muted">' + esc(M.biteSource) + "</p>" +
      "<p>Lava waits 1.6x as long as water, the void 1.8x. Speed shortens the wait: the Lure enchantment and every bait " +
      "on the rod add to the same term. Luck of the Seas does not shorten it, it raises the weight instead.</p>" +
      "<table><tr><th class=\"num\">Lure level / bait speed</th><th class=\"num\">Ticks saved</th>" +
      "<th class=\"num\">Water (avg)</th><th class=\"num\">Lava</th><th class=\"num\">Void</th></tr>" + lureRows + "</table>" +

      "<h2>Field reference</h2>" +
      "<table><tr><th>Key</th><th>Meaning</th></tr>" +
      [["fish", "The fish item this entry spawns."],
       ["bucket", "Bucket item, if the fish can be scooped."],
       ["conditions", "Hard gates. Every one must pass."],
       ["modifiers", "Weight multipliers applied after the gates."],
       ["selection_weight", "Base weight. Higher means more common."],
       ["selection_quality", "Luck coefficient. Added to the weight as quality x luck."],
       ["strength", "Share of the minigame bar that is a miss zone."],
       ["speed", "Minigame movement speed, movements per second."],
       ["behavior", "Which sine-ish curve the fish follows."],
       ["size", "typical_low_cm, typical_high_cm, optional record_low_cm, record_high_cm."],
       ["display_data", "Entity model and offsets used by the fish display block."],
       ["journal_profile", "Journal entry: description key, group, location, rarity."],
       ["shiny_data", "Optional alternate sprite for a shiny variant."],
       ["parent", "Merges a third-party fish into this entry instead of registering a new one."]
      ].map(function (row) {
        return "<tr><td class=\"mono\">" + esc(row[0]) + "</td><td>" + esc(row[1]) + "</td></tr>";
      }).join("") + "</table>" +
      '<div class="note">' + esc(M.rarityNote) + "</div>" + footer();
  }

  /* ------------------------------------------------------------ loadout */

  function pageLoadoutIndex() {
    var q = state.fishQuery.toLowerCase();
    var list = T.fish.filter(function (f) {
      return !q || (f.name + " " + f.location).toLowerCase().indexOf(q) >= 0;
    }).slice(0, 60);
    return "<h1>Loadout planner</h1>" +
      '<p class="sub">Pick a fish, get the rod, hook, line and bait that reach it. ' +
      'Works backwards from the fish\'s own spawn conditions. Open one from any <a href="#/fish">fish page</a>.</p>' +
      '<div class="controls"><input type="search" id="fishSearch" placeholder="Search fish..." value="' + esc(state.fishQuery) + '"></div>' +
      '<div class="cards">' + list.map(function (f) {
        return '<a class="card clickable" href="#/loadout/' + esc(f.id) + '" style="text-decoration:none;color:inherit">' +
          icon(f.id) + '<div class="body"><div class="name">' + esc(f.name) + "</div>" +
          '<div class="meta">' + esc(f.location) + "</div>" + rarityChip(f.rarity) + "</div></a>";
      }).join("") + "</div>" + footer();
  }

  function planFor(f) {
    var fluid = (f.fluids[0] || "water");
    var checks = [];
    var notes = [];
    var mediumName = { lava: "lava", void: "the fishable Void surface", water: "water" }[fluid] || fluid;

    checks.push({ ok: true, label: "Fish in " + mediumName,
      detail: f.fluids.length ? "Required by the fish data." : "Water is the default medium." });

    var lava = f.fluids.indexOf("lava") >= 0;
    var voided = f.fluids.indexOf("void") >= 0;
    var rod, rodReason;
    if (lava) {
      var netherFish = f.dimensions.indexOf("minecraft:the_nether") >= 0;
      var lavaRods = T.rods.filter(function (r) { return r.lavaFishing; });
      rod = netherFish ? lavaRods.filter(function (r) { return r.netherOverride; })[0] || lavaRods[0]
        : lavaRods[lavaRods.length - 1];
      rodReason = "Lava fishing needs a lava fishing rod (Netherite, Blazing) or the Lavaproof Hook. " +
        (rod.netherOverride ? "Blazing counts any lava as Nether lava, so this fish is catchable outside the Nether too."
          : "The Blazing rod does the same and works in any lava.");
    } else {
      var waterRods = T.rods.filter(function (r) { return !r.lavaFishing; });
      rod = waterRods.slice().sort(function (a, b) {
        return ((b.luckBoost ? 1 : 0) - (a.luckBoost ? 1 : 0)) || (b.baitSlots - a.baitSlots);
      })[0];
      var roomiest = waterRods.slice().sort(function (a, b) { return b.baitSlots - a.baitSlots; })[0];
      rodReason = "Any rod works in water. " + rod.name + (rod.luckBoost ? " adds +1 luck" : "") +
        (rod.baitSlots > 1 ? " and carries " + rod.baitSlots + " bait slots, so it takes the most bait at once." : ".");
      if (roomiest.id !== rod.id) {
        rodReason += " For raw capacity the " + roomiest.name + " holds " + roomiest.baitSlots +
          " bait stacks" + (roomiest.bonus ? " (" + roomiest.bonus.toLowerCase() + ")" : "") + ".";
      }
    }

    var hook = { id: "tide:fishing_hook", name: "Fishing Hook", effect: "Default hook.", flags: {} };
    var hookReason = "Nothing about this fish is gated by an accessory.";
    if (voided) {
      hook = T.hooks.filter(function (h) { return h.flags && h.flags["void"]; })[0];
      hookReason = "Void fishing only works with the Hook of the Depths. No rod can do it.";
    } else if (lava && !rod.lavaFishing) {
      hook = T.hooks.filter(function (h) { return h.flags && h.flags.lava; })[0];
      hookReason = "Lavaproof Hook also opens lava, so you can fish lava with any rod you like.";
    } else if (lava) {
      hookReason = "The " + rod.name + " already fishes lava, so the default hook is enough. " +
        "Lavaproof Hook would let you use any other rod instead.";
    }
    var shifted = f.timeRanges.map(function (r) {
      return { min: (r.min + 12000) % 24000, max: (r.max + 12000) % 24000 };
    });
    if (f.timeRanges.length) {
      var twilight = T.hooks.filter(function (h) { return h.flags && h.flags.timeShift; })[0];
      if (hook.id === "tide:fishing_hook" && !f.temperature) {
        hook = twilight;
        hookReason = "This fish only spawns " + f.timeRanges.map(timeWindow).join(" or ") +
          ". The Twilight Hook shifts the test by half a day, moving it to " + shifted.map(timeWindow).join(" or ") +
          ". It is optional: fishing inside the window works too.";
      }
      checks.push({ ok: true, label: "Time window " + f.timeRanges.map(timeWindow).join(", "),
        detail: (hook.flags && hook.flags.timeShift ? "Twilight Hook moves this to " + shifted.map(timeWindow).join(", ") + "." :
          "Fish inside this window. The Twilight Hook would move it to " + shifted.map(timeWindow).join(", ") + ".") });
    }
    if (f.temperature) {
      var t = f.temperature;
      var wanted = toC(t.preferred).toFixed(1);
      var up = toC(tempEdge(t.preferred + 0.25)) - toC(tempEdge(t.preferred));
      var down = toC(tempEdge(t.preferred - 0.25)) - toC(tempEdge(t.preferred));
      checks.push({ ok: false, label: "Water temperature near " + wanted + " °C (" +
        toC(tempEdge(t.preferred - t.tolerance)).toFixed(1) + "–" +
        toC(tempEdge(t.preferred + t.tolerance)).toFixed(1) + " °C)",
        detail: "Weight falls off as a curve and hits zero outside that range. The reading comes from the biome, " +
          "not the depth, so check the Climate Gauge before you cast. The Fiery Hook adds 0.25 to the reading " +
          "and the Permafrost Hook takes 0.25 off, which is " + up.toFixed(1) + " °C and " +
          Math.abs(down).toFixed(1) + " °C around " + wanted + " °C. Take whichever one moves the gauge toward it." +
          (down === 0 ? " Permafrost cannot go colder here, the reading is already at the bottom of the scale." : "") });
      if (hook.id === "tide:fishing_hook") {
        hookReason = "The default hook. Use one only if the Climate Gauge is off its preferred " + wanted +
          " °C, and then take whichever of the Fiery or Permafrost Hook moves the gauge toward it - the " +
          "direction depends on your biome, not on the fish.";
      }
      if (hook.flags && (hook.flags.timeShift || hook.flags.lava || hook.flags["void"])) {
        notes.push("One hook slot only: the " + hook.name + " does nothing for temperature. Save the slot for the " +
          "Fiery or Permafrost Hook and " +
          (f.timeRanges.length ? "fish inside " + f.timeRanges.map(timeWindow).join(" or ") + " instead." :
            "give up on the medium this hook enables."));
      } else if (f.timeRanges.length) {
        notes.push("One hook slot only: the Twilight Hook would move the window to " +
          shifted.map(timeWindow).join(" or ") + " but does nothing for temperature. Fish inside " +
          f.timeRanges.map(timeWindow).join(" or ") + " and keep the slot for a temperature hook.");
      }
    }

    var gate = f.luckGate || 0;
    var strength = typeof f.strength === "number" ? f.strength : 0.3;
    var speed = typeof f.speed === "number" ? f.speed : 1.0;
    var area = Math.min(Math.max(1 - strength, 0.05), 1);

    var line, lineReason;
    if (strength >= 0.6) {
      line = T.lines.filter(function (l) { return l.effects && l.effects.strength === 0.75; })[0];
      lineReason = "strength " + strength + " leaves only " + (area * 100).toFixed(1) +
        "% of the bar. The Diamond Line cuts strength by a quarter.";
    } else if (speed >= 1.5) {
      line = T.lines.filter(function (l) { return l.effects && l.effects.speed === 0.9; })[0];
      lineReason = "speed " + speed + " is quick. The Copper Line slows the fish 10%.";
    } else {
      line = T.lines.filter(function (l) { return !Object.keys(l.effects || {}).length; })[0];
      lineReason = "strength " + strength + " and speed " + speed + " are both mild; a plain line is enough.";
    }

    var bait, baitReason;
    if (gate >= 4 || f.quality > 0) {
      bait = T.baits.filter(function (b) { return b.luck === 2; })[0];
      baitReason = gate ? "This fish needs luck " + gate + " and Lucky Bait is the only +2 source." :
        "This fish has selection_quality " + f.quality + ", so luck raises its weight. Lucky Bait is the biggest single source.";
    } else {
      bait = T.baits.filter(function (b) { return b.item === "tide:bait"; })[0];
      baitReason = "Plain Bait adds +2 fishing speed, which shortens the wait between bites.";
    }

    var hookAlts = f.temperature ? T.hooks.filter(function (h) {
      return h.flags && h.flags.temperature;
    }) : [];

    return { rod: rod, rodReason: rodReason, hook: hook, hookReason: hookReason, line: line,
      lineReason: lineReason, bait: bait, baitReason: baitReason, checks: checks, notes: notes,
      hookAlts: hookAlts, gate: gate, strength: strength, speed: speed, area: area };
  }

  function buildLuck(build) {
    return (build.bait ? build.bait.luck : 0) +
      (build.line && build.line.effects && build.line.effects.luck ? build.line.effects.luck : 0) +
      (build.rod && build.rod.luckBoost ? 1 : 0);
  }

  function luckTable(f, luck) {
    var keys = Object.keys(f.weightsAtLuck);
    return "<table><tr><th>Luck</th>" + keys.map(function (k) {
      return '<th class="num">' + k + "</th>";
    }).join("") + "</tr><tr><td>Weight</td>" + keys.map(function (k) {
      return '<td class="num mono">' + f.weightsAtLuck[k] + "</td>";
    }).join("") + "</tr><tr><td>Share</td>" + keys.map(function (k) {
      return '<td class="num mono">' + pct(f.shareAtLuck[k]) + "</td>";
    }).join("") + "</tr></table>";
  }

  function pageLoadout(id) {
    var f = T.fish.filter(function (x) { return x.id === id; })[0];
    if (!f) return "<h1>Fish not found</h1><p><a href=\"#/loadout\">Back to the planner</a></p>";
    var p = planFor(f);
    var trap = biomeTempWarning(f);

    var maxLuckRod = T.rods.filter(function (r) { return r.luckBoost; })
      .sort(function (a, b) { return b.baitSlots - a.baitSlots; })[0];
    var builds = [
      { name: "Recommended", rod: p.rod, hook: p.hook, line: p.line, bait: p.bait, why: p.lineReason },
      { name: "Max luck", rod: maxLuckRod, hook: p.hook,
        line: T.lines.filter(function (l) { return l.effects && l.effects.luck; })[0],
        bait: T.baits.filter(function (b) { return b.luck === 2; })[0],
        why: "Golden Line + Lucky Bait + a luck rod stacks +4 luck. Swap in the Suncatcher for +5 when you can see the sky." },
      { name: "Easy minigame", rod: p.rod, hook: p.hook,
        line: T.lines.filter(function (l) { return l.effects && l.effects.strength === 0.75; })[0], bait: null,
        why: "Diamond Line for the biggest hit area. No bait needed." }
    ];

    var buildCards = builds.map(function (b) {
      var effects = b.line ? b.line.effects || {} : {};
      var effStrength = p.strength * (effects.strength || 1);
      var effSpeed = p.speed * (effects.speed || 1);
      var luckTotal = buildLuck(b);
      var weight = f.weight + f.quality * luckTotal;
      var lines = [
        b.rod ? "Rod: " + esc(b.rod.name) + (b.rod.bonus ? " (" + esc(b.rod.bonus) + ")" : "") : null,
        b.hook ? "Hook: " + esc(b.hook.name) : null,
        b.line ? "Line: " + esc(b.line.name) : null,
        b.bait ? "Bait: " + esc(b.bait.name) : "Bait: none",
        "Luck " + luckTotal + (f.quality ? " -> weight " + weight.toFixed(2) : ""),
        "Hit area " + (Math.min(Math.max(1 - effStrength, 0.05), 1) * 100).toFixed(1) + "%, speed " + (effSpeed / 20).toFixed(2) + "/s"
      ].filter(Boolean);
      if (p.gate) {
        lines.push(luckTotal >= p.gate ? "Meets the luck " + p.gate + " gate" :
          "Short of the luck " + p.gate + " gate by " + (p.gate - luckTotal) + " - add Suncatcher in sun, Prismarine in rain, or Luck of the Seas");
      }
      return '<div class="card"><div class="body"><div class="name">' + esc(b.name) + "</div>" +
        '<div class="lines">' + lines.join("<br>") + "</div>" +
        '<div class="meta">' + esc(b.why) + "</div></div></div>";
    }).join("");

    var checklist = p.checks.map(function (c) {
      return "<tr><td>" + (c.ok ? "&#10003;" : "!") + "</td><td>" + esc(c.label) +
        (c.detail ? '<div class="small muted">' + esc(c.detail) + "</div>" : "") + "</td></tr>";
    }).join("");

    var where = f.where.filter(function (w) {
      return w.indexOf("Fluid:") !== 0 && w.indexOf("Dimension:") !== 0 && w.indexOf("Needs fishing luck") !== 0;
    });

    return '<div class="crumbs"><a href="#/fish/' + esc(f.id) + '">&larr; ' + esc(f.name) + "</a></div>" +
      '<div class="hero">' + icon(f.id, "lg") +
      '<div><h1>' + esc(f.name) + "</h1>" +
      '<span class="chip">' + esc(f.groupName) + "</span>" + rarityChip(f.rarity) +
      '<span class="chip">' + esc(f.location) + "</span>" +
      '<p style="margin-top:8px">' + esc(f.description) + "</p></div></div>" +

      "<h2>Requirements</h2><table>" + checklist + "</table>" +
      (p.notes.length ? p.notes.map(function (n) { return '<div class="note">' + esc(n) + "</div>"; }).join("") : "") +
      (trap ? '<div class="note"><strong>Temperature trap.</strong> ' + esc(trap) + "</div>" : "") +
      biomeFactsNote(f) +
      (where.length ? "<h3>Where to stand</h3><ul>" + where.map(function (w) {
        return "<li>" + esc(w) + "</li>";
      }).join("") + "</ul>" : "") +
      (p.gate ? '<div class="note">This fish will not spawn below luck <strong>' + p.gate +
        "</strong>. Sources: Lucky Bait +2, Golden Line +1, Golden or Midas rod +1, Suncatcher in sun +1, " +
        "Prismarine rod in rain +1, Luck of the Seas +1 per level.</div>" : "") +

      "<h2>Recommended loadout</h2>" +
      '<div class="cards">' +
      [p.rod, p.hook, p.line, p.bait].concat(p.hookAlts).filter(Boolean).map(function (part) {
        return '<div class="card">' + icon(part.id) + '<div class="body"><div class="name">' + esc(part.name) + "</div>" +
          (part.baitSlots ? '<div class="meta">' + part.baitSlots + " bait slot" + (part.baitSlots > 1 ? "s" : "") +
            " &middot; " + part.durability + " durability</div>" : "") +
          '<div class="lines">' + esc(part.effect || part.bonus || (part.desc || []).join(" ") || "") + "</div></div></div>";
      }).join("") + "</div>" +
      "<table>" +
      "<tr><th>Part</th><th>Why</th></tr>" +
      "<tr><td>Rod</td><td>" + esc(p.rodReason) + "</td></tr>" +
      "<tr><td>Hook</td><td>" + esc(p.hookReason) + "</td></tr>" +
      "<tr><td>Line</td><td>" + esc(p.lineReason) + "</td></tr>" +
      "<tr><td>Bait</td><td>" + esc(p.baitReason) + "</td></tr>" +
      "<tr><td>Bobber</td><td>Cosmetic only. Any of the " + T.items.filter(function (i) {
        return i.tags.indexOf("bobbers") >= 0; }).length + " bobbers changes nothing about the odds.</td></tr>" +
      "</table>" +

      "<h2>Alternative builds</h2><div class=\"cards\">" + buildCards + "</div>" +

      "<h2>Numbers</h2>" + luckTable(f, 0) +
      '<p class="muted small">Share is this fish\'s weight divided by the total weight of the ' + f.pool +
      " fish that share its medium and dimension. Biome, depth, time and weather filters are not applied, " +
      "so real odds are usually better in the right spot.</p>" +
      "<table><tr><th>Value</th><th class=\"num\">Raw</th><th class=\"num\">With " + esc(p.line.name) + "</th></tr>" +
      "<tr><td>Hit area</td><td class=\"num mono\">" + (p.area * 100).toFixed(1) + "%</td><td class=\"num mono\">" +
      (Math.min(Math.max(1 - p.strength * ((p.line.effects || {}).strength || 1), 0.05), 1) * 100).toFixed(1) + "%</td></tr>" +
      "<tr><td>Movements per second</td><td class=\"num mono\">" + (p.speed / 20).toFixed(2) + "</td><td class=\"num mono\">" +
      (p.speed * ((p.line.effects || {}).speed || 1) / 20).toFixed(2) + "</td></tr>" +
      "<tr><td>Luck from loadout</td><td class=\"num mono\">0</td><td class=\"num mono\">" + buildLuck({ rod: p.rod, line: p.line, bait: p.bait }) + "</td></tr>" +
      "<tr><td>Size median</td><td class=\"num mono\" colspan=\"2\">" + (f.sizeStats ? f.sizeStats.p50 : "-") + " cm</td></tr>" +
      "<tr><td>Cooks into</td><td class=\"mono\" colspan=\"2\">" + esc(f.cookTier ? f.cookTier.replace(/_/g, " ") : "not cookable") + "</td></tr>" +
      "<tr><td>Bite wait multiplier</td><td class=\"num mono\" colspan=\"2\">" +
      esc(String(T.mechanics.mediumMultipliers[mediumKey(f)] || 1)) + "x</td></tr>" +
      "</table>" + footer();
  }

  function mediumKey(f) {
    if (f.fluids.indexOf("lava") >= 0) return "lava";
    if (f.fluids.indexOf("void") >= 0) return "void";
    return "water";
  }

  /* ------------------------------------------------------------ router */

  var PAGES = {
    "#/": pageOverview,
    "#/fish": pageFish,
    "#/loadout": pageLoadoutIndex,
    "#/items": pageItems,
    "#/blocks": pageBlocks,
    "#/recipes": pageRecipes,
    "#/crates": pageCrates,
    "#/minigame": pageMinigame,
    "#/stats": pageStats,
    "#/config": pageConfig,
    "#/commands": pageCommands,
    "#/advancements": pageAdvancements,
    "#/compat": pageCompat
  };

  function navHtml() {
    var m = T.meta;
    return '<div class="brand"><img src="' + m.icon + '" alt=""><div><b>shae&#39;s tide 2</b><small>wiki</small></div></div>' +
      NAV.map(function (item) {
        return (item.group ? '<div class="group">' + (item.hash === "#/fish" ? "Content" : "Building") + "</div>" : "") +
          '<a href="' + item.hash + '" data-nav="' + item.hash + '">' + esc(item.label) + "</a>";
      }).join("");
  }

  var lastHash = null;

  function render() {
    var hash = location.hash || "#/";
    var html, active = hash;
    if (hash.indexOf("#/fish/") === 0) {
      html = pageFishDetail(hash.slice("#/fish/".length));
      active = "#/fish";
    } else if (hash.indexOf("#/loadout/") === 0) {
      html = pageLoadout(hash.slice("#/loadout/".length));
      active = "#/loadout";
    } else if (PAGES[hash]) {
      html = PAGES[hash]();
    } else {
      html = "<h1>Not found</h1><p><a href=\"#/\">Back to the overview</a></p>";
    }

    var nav = document.querySelector("nav");
    if (!nav) {
      nav = document.createElement("nav");
      document.getElementById("app").insertBefore(nav, document.querySelector("main"));
    }
    nav.innerHTML = navHtml();

    var main = document.querySelector("main");
    if (!main) {
      main = document.createElement("main");
      document.getElementById("app").appendChild(main);
    }
    var focused = document.activeElement && document.activeElement.id;
    main.innerHTML = html;
    var link = nav.querySelector('[data-nav="' + active + '"]');
    if (link) link.classList.add("active");
    if (focused) {
      var again = document.getElementById(focused);
      if (again) { again.focus(); again.setSelectionRange(again.value.length, again.value.length); }
    }
    if (lastHash !== hash) window.scrollTo(0, 0);
    lastHash = hash;
  }

  document.addEventListener("click", function (event) {
    var target = event.target.closest("[data-filter],[data-cat],[data-pagekey]");
    if (!target) return;
    if (target.dataset.filter === "group") { state.fishGroup = target.dataset.value; state.fishPage = 0; }
    else if (target.dataset.filter === "rarity") { state.fishRarity = target.dataset.value; state.fishPage = 0; }
    else if (target.dataset.cat) { recipeCat = target.dataset.cat; }
    else if (target.dataset.pagekey) { state[target.dataset.pagekey] = parseInt(target.dataset.value, 10) || 0; }
    else return;
    event.preventDefault();
    render();
  });

  document.addEventListener("input", function (event) {
    if (event.target.id === "fishSearch") { state.fishQuery = event.target.value; state.fishPage = 0; render(); }
    else if (event.target.id === "itemSearch") { state.itemQuery = event.target.value; render(); }
  });

  window.addEventListener("hashchange", render);
  startSpriteFlipper();
  render();
})();
